import csv
import json
import math
import re
from datetime import datetime
from collections import defaultdict

DATA_PATH = "/app/dataset/data.csv"


def parse_amount(value):
    raw = (value or "").strip()
    if not raw:
        return math.nan

    negative = (
        re.search(r"\bCR\b", raw, flags=re.IGNORECASE) is not None
        or (raw.startswith("(") and raw.endswith(")"))
        or "-" in raw
    )

    # Remove the known currency tokens, then retain only numeric punctuation.
    cleaned = re.sub(r"C[12]", "", raw, flags=re.IGNORECASE)
    cleaned = re.sub(r"[^0-9,.]", "", cleaned)
    if not cleaned or not any(ch.isdigit() for ch in cleaned):
        return math.nan

    comma_present = "," in cleaned
    dot_present = "." in cleaned
    decimal_pos = None

    if comma_present and dot_present:
        # The rightmost separator is the decimal separator.
        decimal_pos = max(cleaned.rfind(","), cleaned.rfind("."))
    elif comma_present or dot_present:
        sep = "," if comma_present else "."
        pos = cleaned.rfind(sep)
        digits_after = sum(ch.isdigit() for ch in cleaned[pos + 1 :])
        if digits_after == 2:
            decimal_pos = pos

    if decimal_pos is None:
        number_text = "".join(ch for ch in cleaned if ch.isdigit())
    else:
        integer_part = "".join(ch for ch in cleaned[:decimal_pos] if ch.isdigit())
        fractional_part = "".join(ch for ch in cleaned[decimal_pos + 1 :] if ch.isdigit())
        number_text = integer_part + "." + fractional_part

    if number_text in ("", "."):
        return math.nan
    amount = float(number_text)
    return -amount if negative else amount


def parse_notes(notes):
    text = notes or ""
    m = re.search(r"\bitems\s*=\s*([+-]?\d+)\b", text, flags=re.IGNORECASE)
    items = int(m.group(1)) if m else None

    m = re.search(r"\badj\s*=\s*([+-]?(?:\d+(?:\.\d*)?|\.\d+))\s*%", text, flags=re.IGNORECASE)
    adj_pct = float(m.group(1)) / 100.0 if m else 0.0

    m = re.search(r"\bfee\s*=\s*([+-]?(?:\d+(?:\.\d*)?|\.\d+))\b", text, flags=re.IGNORECASE)
    fee = float(m.group(1)) if m else 0.0

    waive = re.search(r"\bwaive\s*=\s*true\b", text, flags=re.IGNORECASE) is not None
    return items, adj_pct, fee, waive


def parse_event_time(value):
    if not value:
        return None
    # The file uses one consistent ISO-like timestamp format and timezone.
    return datetime.fromisoformat(value.replace("Z", "+00:00"))


def answer() -> list[str]:
    rows = []
    with open(DATA_PATH, newline="", encoding="utf-8") as f:
        for file_order, row in enumerate(csv.DictReader(f)):
            event_time = parse_event_time(row["event_time"].strip())
            base_amount = parse_amount(row["amount_str"])
            items, adj_pct, fee, waive = parse_notes(row["notes"])
            net = math.nan if math.isnan(base_amount) else base_amount * (1.0 + adj_pct) + fee
            if waive and not math.isnan(base_amount):
                net = 0.0
            rows.append({
                "record_id": row["record_id"],
                "event_time": event_time,
                "region": row["region"],
                "channel": row["channel"],
                "items": items,
                "net": net,
                "file_order": file_order,
            })

    # Latest event_time wins. For equal timestamps, prefer finite net, then file order.
    latest_by_id = {}
    for row in rows:
        key = row["record_id"]
        prior = latest_by_id.get(key)
        if prior is None:
            latest_by_id[key] = row
            continue
        time_key = row["event_time"]
        prior_time = prior["event_time"]
        if time_key is None:
            time_rank = float("-inf")
        else:
            time_rank = time_key.timestamp()
        if prior_time is None:
            prior_time_rank = float("-inf")
        else:
            prior_time_rank = prior_time.timestamp()
        if time_rank > prior_time_rank:
            latest_by_id[key] = row
        elif time_rank == prior_time_rank:
            row_real = math.isfinite(row["net"])
            prior_real = math.isfinite(prior["net"])
            if row_real and not prior_real:
                latest_by_id[key] = row
            elif row_real == prior_real and row["file_order"] < prior["file_order"]:
                latest_by_id[key] = row

    start = datetime.fromisoformat("2025-10-01T00:00:00+00:00")
    end = datetime.fromisoformat("2025-12-31T23:59:59+00:00")
    filtered = []
    for row in latest_by_id.values():
        t = row["event_time"]
        if t is None or not (start <= t <= end):
            continue
        if row["channel"].casefold() == "phone":
            continue
        if not math.isfinite(row["net"]):
            continue
        row["month"] = t.strftime("%Y-%m")
        filtered.append(row)

    groups = defaultdict(list)
    for row in filtered:
        groups[(row["region"], row["month"])].append(row)

    for group in groups.values():
        values = sorted(row["net"] for row in group)
        n = len(values)
        if n % 2:
            median = values[n // 2]
        else:
            median = (values[n // 2 - 1] + values[n // 2]) / 2.0
        deviations = sorted(abs(row["net"] - median) for row in group)
        if n % 2:
            mad = deviations[n // 2]
        else:
            mad = (deviations[n // 2 - 1] + deviations[n // 2]) / 2.0
        for row in group:
            robust_z = 0.0 if mad == 0 else 0.6745 * (row["net"] - median) / mad
            items_eff = max(1, row["items"] if row["items"] is not None else 1)
            row["abs_robust_z"] = abs(robust_z)
            row["anomaly_score"] = abs(robust_z) * math.log1p(items_eff)

    # Explicit stable sort implements the requested order of tie breakers.
    filtered.sort(key=lambda r: (
        -r["anomaly_score"],
        -r["abs_robust_z"],
        -r["event_time"].timestamp(),
        r["record_id"],
    ))
    return [row["record_id"] for row in filtered[:10]]


if __name__ == "__main__":
    with open("/app/answer.json", "w", encoding="utf-8") as f:
        json.dump(answer(), f, default=list)
